mod sync;

pub use sync::{SyncState, SyncStatusPayload};

use std::fmt;
use std::str::FromStr;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// A journal entry's unique identifier. Generated by the frontend on entry
/// creation; the backend only stores and looks entries up by it.
///
/// ts-rs warns that it cannot parse `#[serde(transparent)]`. That is benign
/// here: its default handling of a single-field tuple struct already emits
/// the inner type, so `Id.ts` is `string` either way. The warning is left
/// on rather than silenced with ts-rs's `no-serde-warnings`, which would
/// also hide a genuinely dropped `rename`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(transparent)]
pub struct Id(Uuid);

impl Id {
    pub fn new() -> Self {
        Self(Uuid::new_v4())
    }
}

impl Default for Id {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Display for Id {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.0, f)
    }
}

impl FromStr for Id {
    type Err = uuid::Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Ok(Self(Uuid::from_str(s)?))
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(rename_all = "snake_case")]
pub struct Header {
    pub id: Id,
    pub title: String,
    pub updated_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
pub struct Entry {
    #[serde(flatten)]
    pub header: Header,
    pub markdown: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Mirrors what the frontend sends over `invoke`. Keep this literal
    /// hand-written: building it from the Rust type would only test serde
    /// against itself, and this is the runtime counterpart to the
    /// compile-time guarantee `src/bindings/` gives.
    #[test]
    fn frontend_json_deserializes_into_entry() {
        let json = r##"{"id":"5c1f7c9e-6e8b-4a2f-9c1a-1f6b9b6b0a01","title":"t",
                       "updated_at":"2026-09-07T20:17:50Z","markdown":"# h"}"##;

        let entry: Entry = serde_json::from_str(json).unwrap();

        assert_eq!(entry.header.title, "t");
        assert_eq!(entry.markdown, "# h");
    }

    /// The `list_entries`/`get_entry` direction. Rust names the wire
    /// format and the generated bindings follow, so the assertion is that
    /// the field keeps its Rust spelling.
    #[test]
    fn header_serializes_snake_case_keys() {
        let header = Header {
            id: "5c1f7c9e-6e8b-4a2f-9c1a-1f6b9b6b0a01".parse().unwrap(),
            title: "t".to_string(),
            updated_at: "2026-09-07T20:17:50Z".parse().unwrap(),
        };

        let value = serde_json::to_value(&header).unwrap();

        assert!(value.get("updated_at").and_then(|v| v.as_str()).is_some());
        assert!(value.get("updatedAt").is_none());
    }
}
